def edit_distance(a, b):
    # table[i][j]: the distance between the first i characters of a and the first j characters of b
    table = [[0] * (len(b) + 1) for _ in range(len(a) + 1)]
    for i in range(len(a) + 1):
        table[i][0] = i                  # turning i characters into nothing: i deletions
    for j in range(len(b) + 1):
        table[0][j] = j                  # building j characters from nothing: j insertions
    for i in range(1, len(a) + 1):
        for j in range(1, len(b) + 1):
            if a[i - 1] == b[j - 1]:
                table[i][j] = table[i - 1][j - 1]            # the last characters agree: no edit needed
            else:
                table[i][j] = 1 + min(table[i - 1][j],        # delete a[i - 1]
                                      table[i][j - 1],        # insert b[j - 1]
                                      table[i - 1][j - 1])    # replace a[i - 1] by b[j - 1]
    return table[len(a)][len(b)]
